guide('unbanz-est-il-fiable', 'is-unbanz-legit',
    'Unbanz est-il fiable ? Ce que vous pouvez vérifier | Unbanz', 'Unbanz est-il fiable ?',
    'Unbanz est-il fiable ?',
    'Unbanz est un service indépendant qui aide à présenter des demandes de réexamen et des signalements via les outils officiels de Meta et de Snapchat. Vous parlez directement à l’équipe, le prix vous est indiqué avant le début du travail et votre mot de passe reste chez vous. Des témoignages vidéo de clients, avec transcription, sont sur la page <a href="/fr/avis/">Avis</a>. Unbanz n’est pas affilié à Meta, ni à Unbanx.',
    [('verifier', 'Ce que vous pouvez vérifier vous-même',
      '<ul><li><strong>Un seul site</strong> : unbanz.com.</li><li><strong>Un seul numéro WhatsApp</strong> : celui des boutons de ce site, et une seule adresse e-mail officielle : <strong>team@unbanz.com</strong>. Sur les réseaux : @unbanzhq (Instagram et X).</li><li><strong>Des témoignages vidéo</strong> de clients, avec transcription, sur <a href="/fr/avis/">la page Avis</a>. Ils sont en anglais.</li><li><strong>Le prix avant le travail</strong> : nous vous l’indiquons dans la discussion, après que vous nous avez expliqué votre situation.</li><li><strong>Aucun mot de passe</strong> demandé : nous partons du nom d’utilisateur et de la notification.</li></ul>'),
     ('limites', 'Ce que nous ne pouvons pas faire',
      '<p>Nous ne sommes pas Meta et nous n’avons pas de pouvoir sur ses décisions. Nous passons par les mêmes voies officielles que vous : demandes de réexamen, signalements, formulaires. C’est la plateforme qui décide, et aucun service extérieur ne peut vous assurer un résultat. Nous vous disons franchement si une demande nous paraît jouable avant de commencer, et nous refusons les demandes contraires aux règles : faux signalements, signalements en masse, achat de comptes, contournement de restrictions.</p>'),
     ('france', 'Un service qui travaille en anglais',
      '<p>Nos échanges se font principalement en anglais, par WhatsApp ou par e-mail. Un message court avec le pseudo, la capture d’écran et la date suffit pour démarrer. Si cela ne vous convient pas, mieux vaut le savoir avant de commencer.</p>'),
     ('unbanx', 'Unbanz, avec un z',
      '<p>Unbanz n’a aucun lien avec Unbanx ou unbanx.me. Les avis et les alertes qui parlent d’Unbanx ne concernent pas Unbanz. Voir <a href="/fr/unbanz-vs-unbanx/">Unbanz ou Unbanx : la différence</a>.</p>'),
     ('remboursement', 'Unbanz rembourse-t-il ?',
      '<p>Pour les réclamations de pseudo, oui : Remboursement intégral à 100\u00a0% si la réclamation du nom d’utilisateur échoue. Pour les autres services, les conditions de remboursement éventuelles sont convenues avec vous avant le début du travail, en même temps que le prix.</p>'),
     ('prudence', 'Comment juger n’importe quel service de récupération',
      '<p>Méfiez-vous de ceux qui vous contactent en premier, demandent votre mot de passe, promettent un résultat assuré ou prétendent connaître quelqu’un chez Meta. Voir <a href="/fr/faux-hackers-arnaque-recuperation-compte/">les arnaques à la récupération de compte</a>.</p>')],
    [('Unbanz est-il fiable ?', 'Unbanz est un service indépendant et payant, avec un site, une adresse e-mail et un numéro WhatsApp officiels. Le prix est indiqué avant le début du travail et le mot de passe reste chez le client. Des témoignages vidéo de clients sont sur la page Avis.'),
     ('Unbanz est-il une arnaque ?', 'Non : c’est un vrai service avec un seul site, une seule adresse e-mail et un seul numéro WhatsApp. Nous ne demandons jamais votre mot de passe ni vos codes. Ne faites confiance à aucun message qui prétend venir d’Unbanz en dehors de ces canaux.'),
     ('Unbanz demande-t-il mon mot de passe ?', 'Non. Il nous suffit de votre nom d’utilisateur et de la notification. Votre mot de passe et vos codes restent chez vous.'),
     ('Unbanz rembourse-t-il ?', 'Pour les réclamations de pseudo, oui : Remboursement intégral à 100\u00a0% si la réclamation du nom d’utilisateur échoue. Pour les autres services, les conditions de remboursement éventuelles sont convenues avec vous avant le début du travail, en même temps que le prix.'),
     ('Où lire des avis sur Unbanz ?', 'Des témoignages vidéo de clients, avec transcription en anglais, sont sur la page Avis de ce site. Nous ne publions pas de note chiffrée.'),
     ('Unbanz fait-il partie de Meta ?', 'Non. Unbanz est un service indépendant, non affilié à Meta, Instagram, Facebook ou Snapchat.'),
     ('Unbanz est-il le même qu’Unbanx ?', 'Non. Unbanz (avec un z) est le service de comptes Instagram, Facebook et Snapchat de unbanz.com. Il n’a aucun lien avec Unbanx ni unbanx.me.')],
    ['avis', 'unbanz-vs-unbanx', 'comment-ca-marche', 'prix-recuperation-compte', 'faux-hackers-arnaque-recuperation-compte'],
    '<p>Pour nous écrire : <a href="/fr/contact/">page contact</a>. Demander ne coûte rien et ne vous engage à rien.</p>', std=False, crumb_label='Services')

guide('unbanz-vs-unbanx', 'unbanz-vs-unbanx',
    'Unbanz ou Unbanx : quelle différence ? | Unbanz', 'Unbanz ou Unbanx ?',
    'Unbanz ou Unbanx : quelle différence ?',
    'Unbanz (avec un z) est le service de comptes Instagram, Facebook et Snapchat de unbanz.com. Unbanx et unbanx.me sont des noms distincts, sans lien avec nous : les avis ou alertes qui concernent Unbanx ne parlent pas d’Unbanz. Nous ne sommes affiliés ni à Unbanx, ni à Meta.',
    [('reponse', 'La réponse courte',
      '<p>Les deux noms ne diffèrent que d’une lettre, et c’est tout ce qu’ils ont en commun.</p><ul><li><strong>Unbanz (avec un z)</strong> : unbanz.com. Service indépendant pour les comptes Instagram, Facebook et Snapchat : demandes de réexamen, signalements, pseudos et comptes publicitaires. E-mail : team@unbanz.com. Réseaux : @unbanzhq.</li><li><strong>Unbanx (avec un x)</strong> : ce n’est ni un service de comptes, ni nous. Selon les informations publiques, l’ancien Unbanx était une application irlandaise de récompenses qui n’est plus en activité, et unbanx.me se présente comme une plateforme d’investissement en cryptomonnaies.</li></ul>'),
     ('avis', 'Vous lisez des avis ? Vérifiez l’orthographe',
      '<p>Les moteurs de recherche confondent parfois les deux noms. Si un avis, une note ou un « vérificateur d’arnaques » parle d’Unbanx ou de unbanx.me, il concerne une autre entreprise. Les témoignages de clients d’Unbanz sont sur <a href="/fr/avis/">la page Avis</a>, en vidéo et avec transcription.</p>'),
     ('canaux', 'Comment reconnaître Unbanz',
      '<p>Notre site est unbanz.com, notre adresse e-mail officielle team@unbanz.com et nos réseaux @unbanzhq. Nous ne demandons jamais votre mot de passe ni vos codes. Voir aussi <a href="/fr/unbanz-est-il-fiable/">Unbanz est-il fiable ?</a></p>')],
    [('Unbanz et Unbanx, est-ce la même entreprise ?', 'Non. Unbanz (avec un z) n’a aucun lien avec Unbanx ni avec unbanx.me.'),
     ('Les avis sur Unbanx concernent-ils Unbanz ?', 'Non. Un avis qui cite Unbanx ou unbanx.me parle d’une autre entreprise.'),
     ('Que fait Unbanz ?', 'Unbanz aide à présenter des demandes de réexamen pour des comptes Instagram, Facebook et Snapchat désactivés ou verrouillés, à signaler des faux comptes via les outils officiels, à demander des pseudos et à remettre de l’ordre dans des comptes publicitaires Meta.'),
     ('Unbanz est-il affilié à Meta ?', 'Non. Service indépendant, non affilié à Meta.'),
     ('Comment contacter le vrai Unbanz ?', 'Par le site unbanz.com, par WhatsApp via les boutons du site, par e-mail à team@unbanz.com ou via @unbanzhq. Toute autre source n’est pas nous.')],
    ['unbanz-est-il-fiable', 'avis', 'services', 'comment-ca-marche'],
    '<p>Pour nous écrire en toute sécurité : <a href="/fr/contact/">page contact</a>.</p>', std=False, crumb_label='Services')

guide('prix-recuperation-compte', 'unban-pricing',
    'Combien coûte la récupération d’un compte Instagram ou Facebook ? | Unbanz', 'Prix et délais',
    'Combien coûte la récupération d’un compte Instagram ou Facebook ?',
    'Le prix dépend du compte, de la plateforme et du travail nécessaire. Chez Unbanz, nous l’indiquons dans la discussion, après que vous nous avez expliqué votre situation et avant que le travail commence ; poser la question ne coûte rien. Quant aux délais, Meta n’en publie pas et nous ne pouvons en promettre aucun.',
    [('prix', 'Ce qui influe sur le prix',
      '<ul><li>La plateforme (Instagram, Facebook, Snapchat, compte publicitaire Meta).</li><li>Le type de situation : désactivation, suspension, piratage, signalement de faux compte, demande de pseudo.</li><li>Le nombre de comptes ou de signalements.</li><li>Le travail à préparer : justificatifs, vérifications, suivi.</li></ul><p>Nous préférons le dire clairement : un prix donné sans avoir compris la situation ne vaut rien.</p>'),
     ('envoyer', 'Ce que nous demandons pour vous répondre',
      '<p>Votre nom d’utilisateur ou le lien du profil, une capture d’écran de la notification et la date. Pour un compte publicitaire, l’identifiant du compte. Jamais de mot de passe ni de code.</p>'),
     ('gratuit', 'Les démarches officielles sont gratuites',
      '<p>Contester une désactivation, utiliser instagram.com/hacked ou signaler un compte ne coûte rien : ce sont les démarches officielles, que vous pouvez faire seul(e). Notre rôle est d’aider quand elles échouent, quand le message n’est pas clair, ou quand vous préférez déléguer. Lisez d’abord <a href="/fr/compte-instagram-desactive-comment-recuperer/">le guide de contestation</a>.</p>'),
     ('remboursement', 'Réclamation de pseudo : remboursement',
      '<p>Remboursement intégral à 100\u00a0% si la réclamation du nom d’utilisateur échoue. Une réclamation échoue lorsque le pseudo n’est pas obtenu sur votre profil. Cette politique concerne uniquement les réclamations de pseudo.</p>'),
     ('delais', 'Et les délais ?',
      '<p>Meta et Snapchat ne publient pas de délai de traitement. Selon les situations, une réponse peut arriver en quelques jours ou en plusieurs semaines. Nous ne promettons aucune date ; nous vous tenons informé(e) de l’avancement. Voir <a href="/fr/faire-appel-instagram-desactive-delai/">le délai d’un appel Instagram</a>.</p>'),
     ('alerte', 'Signaux d’alerte sur les prix',
      '<ul><li>Un prix affiché sans aucune question sur votre situation.</li><li>Un service qui vous contacte en premier.</li><li>Une demande de mot de passe, de code ou d’accès à l’e-mail.</li><li>Une promesse de résultat assuré.</li></ul><p>Voir <a href="/fr/faux-hackers-arnaque-recuperation-compte/">les arnaques à la récupération de compte</a>.</p>')],
    [('Combien coûte la récupération d’un compte Instagram ?', 'Cela dépend du compte et de la situation. Chez Unbanz, le prix est indiqué dans la discussion après que vous avez expliqué ce qui s’est passé, avant le début du travail.'),
     ('Demander un devis coûte-t-il quelque chose ?', 'Non. Demander ne coûte rien et ne vous engage à rien.'),
     ('Combien de temps faut-il pour récupérer un compte ?', 'Meta ne publie pas de délai. Selon les situations, cela va de quelques jours à plusieurs semaines. Nous ne pouvons promettre aucune date.'),
     ('Puis-je le faire gratuitement moi-même ?', 'Oui, les démarches officielles (contestation, instagram.com/hacked, signalement) sont gratuites. Notre aide s’adresse à ceux qui veulent déléguer ou dont la demande n’avance pas.'),
     ('Dois-je envoyer mon mot de passe pour avoir un prix ?', 'Non. Un nom d’utilisateur et une capture d’écran suffisent. Ne partagez jamais votre mot de passe ni vos codes.'),
     ('Y a-t-il un tarif affiché sur le site ?', 'Non, car le prix dépend de la situation. Il vous est communiqué dans la discussion, avant le début du travail.'),
     ('Que se passe-t-il si la réclamation de mon pseudo échoue ?', 'Vous êtes remboursé(e) intégralement, à 100\u00a0%. Si le pseudo n’est pas obtenu sur votre profil, nous vous remboursons la totalité de ce que vous avez payé pour la réclamation.')],
    ['comment-ca-marche', 'unbanz-est-il-fiable', 'faire-appel-instagram-desactive-delai', 'faux-hackers-arnaque-recuperation-compte', 'contact'],
    '<p>Pour obtenir un prix : <a href="/fr/contact/">écrivez-nous</a> avec le pseudo et la capture d’écran de la notification.</p>', std=False, crumb_label='Services')

guide('droit-de-recours-dsa-meta', None,
    'DSA : contester une décision d’Instagram ou Facebook en Europe | Unbanz', 'Recours DSA (Europe)',
    'Contester une décision d’Instagram ou Facebook en Europe : le recours DSA.',
    'Dans l’Union européenne, le règlement sur les services numériques (DSA) vous donne le droit de contester une décision de modération d’Instagram ou Facebook : d’abord via le système interne de réclamation de la plateforme, puis, si vous le souhaitez, devant un organisme de règlement extrajudiciaire des litiges certifié, comme Appeals Centre Europe. Ces organismes rendent des décisions non contraignantes, mais les plateformes doivent y participer de bonne foi.',
    [('droits', 'Ce que le DSA prévoit',
      '<ul><li>La plateforme doit vous <strong>expliquer sa décision</strong> (motif et recours possibles).</li><li>Elle doit proposer un <strong>système interne de réclamation</strong>, accessible pendant au moins six mois après la décision.</li><li>Vous pouvez saisir un <strong>organisme de règlement extrajudiciaire des litiges</strong> certifié dans l’Union européenne.</li><li>Vous pouvez aussi adresser une plainte au <strong>coordinateur pour les services numériques</strong> de votre pays (en France, l’Arcom).</li></ul>'),
     ('ace', 'Appeals Centre Europe',
      '<p>Appeals Centre Europe est un organisme indépendant certifié au titre du DSA par le régulateur irlandais (Coimisiún na Meán). Il traite les litiges liés aux décisions de modération de plusieurs plateformes, dont Facebook et Instagram : compte suspendu ou restreint, contenu retiré, Page ou groupe retiré.</p><ul><li><strong>Coût</strong> : d’après son site, il n’y a actuellement pas de frais pour l’utilisateur. Un éventuel frais futur de 5 € est évoqué dans son règlement ; vérifiez les conditions en vigueur.</li><li><strong>Délai de dépôt</strong> : pour un compte ou un contenu retiré ou suspendu, la décision de la plateforme doit dater de moins de six mois.</li><li><strong>Délai de traitement</strong> : l’organisme vise une décision sous 90 jours, jusqu’à 180 jours pour les litiges complexes.</li><li><strong>Nature de la décision</strong> : non contraignante, mais la plateforme doit s’engager de bonne foi et peut revenir sur sa décision.</li><li><strong>Appel interne</strong> : il n’est pas obligatoire d’y avoir recours d’abord, mais l’organisme le recommande.</li></ul><p>D’autres organismes sont certifiés, par exemple User Rights. La liste officielle est publiée par la Commission européenne.</p>'),
     ('limites', 'Ce qu’il faut savoir avant de se lancer',
      '<ul><li>Ce recours concerne les décisions de modération prises par la plateforme. Vérifiez sur le site de l’organisme que votre situation est éligible (par exemple, ce que couvrent les comptes publicitaires).</li><li>Il ne remplace pas l’appel dans l’application : commencez par lui, en gardant vos captures d’écran.</li><li>Aucun résultat n’est assuré, ni pour vous, ni pour nous.</li></ul>' + OFFICIEL)],
    [('Peut-on contester une décision d’Instagram devant un organisme européen ?', 'Oui. Dans l’UE, le DSA permet de saisir un organisme de règlement extrajudiciaire des litiges certifié, comme Appeals Centre Europe, pour une décision de modération d’Instagram ou de Facebook.'),
     ('Appeals Centre Europe est-il payant ?', 'D’après son site, il n’y a actuellement pas de frais pour l’utilisateur. Un frais de 5 € est prévu dans son règlement s’il était introduit : vérifiez les conditions en vigueur.'),
     ('Combien de temps ai-je pour saisir un organisme DSA ?', 'Pour un compte retiré ou suspendu, la décision de la plateforme doit dater de moins de six mois, d’après Appeals Centre Europe.'),
     ('La décision de l’organisme s’impose-t-elle à Meta ?', 'Non, elle n’est pas contraignante. Mais la plateforme doit participer de bonne foi, et sa décision peut être revue.'),
     ('Dois-je faire appel dans l’application avant ?', 'Ce n’est pas obligatoire, mais c’est recommandé. Commencez par l’appel dans l’application et gardez les captures d’écran.'),
     ('Peut-on aussi se plaindre à l’Arcom ?', 'Le DSA prévoit un droit de plainte auprès du coordinateur pour les services numériques de votre pays. En France, c’est l’Arcom.')],
    ['instagram-appel-refuse', 'instagram-pas-de-bouton-faire-appel', 'compte-instagram-desactive-comment-recuperer', 'compte-facebook-desactive-faire-appel'],
    '<p>Un recours externe demande des informations précises (dates, captures d’écran, décision contestée). Si vous souhaitez de l’aide pour les rassembler, <a href="/fr/contact/">écrivez-nous</a> : nous vous disons honnêtement si une démarche a du sens. Nous ne donnons pas de conseil juridique.</p>', std=False)

guide('contacter-instagram-meta-support-france', None,
    'Contacter le support Instagram ou Meta en France : ce qui existe | Unbanz', 'Support Meta en France',
    'Contacter le support Instagram ou Meta en France : ce qui existe.',
    'Instagram n’a pas de numéro de téléphone ni de chat accessible à tous les utilisateurs : on passe par le centre d’aide, les formulaires officiels et les écrans de contestation dans l’application. Certains abonnés Meta Verified et annonceurs éligibles ont accès à une assistance supplémentaire, selon leur pays. Méfiez-vous de tout numéro « support Instagram » trouvé en ligne.',
    [('existe', 'Ce qui existe',
      '<ul><li>Le <a href="https://help.instagram.com/" rel="noopener" target="_blank">centre d’aide Instagram</a> et celui de Facebook, avec des formulaires pour signaler un problème.</li><li>Les écrans de contestation dans l’application, quand une mesure est prise sur votre compte.</li><li>Pour certains abonnés <strong>Meta Verified</strong> et certains annonceurs, une assistance par chat selon l’éligibilité et le pays.</li><li>Le <a href="/fr/droit-de-recours-dsa-meta/">recours DSA</a> pour contester une décision de modération en Europe.</li></ul>'),
     ('nexiste', 'Ce qui n’existe pas',
      '<ul><li>Pas de numéro de téléphone public pour tous les utilisateurs.</li><li>Pas d’adresse e-mail « secrète » pour faire réactiver un compte : les listes d’adresses qui circulent sur les forums ne sont pas une voie de recours.</li><li>Pas de service extérieur qui ait une ligne directe avec Meta. Unbanz non plus : nous passons par les mêmes voies officielles que vous.</li></ul>'),
     ('arnaques', 'Attention aux faux numéros',
      '<p>Des numéros présentés comme « support Instagram » ou « support Facebook » circulent en ligne. Ce sont fréquemment des arnaques qui demandent vos codes ou un paiement. Ne communiquez jamais votre mot de passe ni un code reçu par SMS. Voir <a href="/fr/faux-hackers-arnaque-recuperation-compte/">les arnaques à la récupération de compte</a>.</p>'),
     ('bien', 'Bien préparer sa demande',
      '<ul><li>Capture d’écran de la notification, avec la date.</li><li>E-mail et téléphone du compte à portée de main.</li><li>Une seule demande, claire, plutôt que dix.</li></ul>' + OFFICIEL)],
    [('Quel est le numéro de téléphone du support Instagram en France ?', 'Il n’existe pas de numéro général pour les utilisateurs. Les numéros « support Instagram » trouvés en ligne sont souvent des arnaques.'),
     ('Comment contacter Meta quand mon compte est désactivé ?', 'Passez par l’écran de contestation dans l’application et le centre d’aide. En Europe, un recours DSA est possible pour contester la décision.'),
     ('Y a-t-il un chat de support Instagram ?', 'Pas pour tous. Certains abonnés Meta Verified et annonceurs éligibles ont accès à une assistance, selon leur pays.'),
     ('Peut-on écrire un e-mail à Instagram pour récupérer un compte ?', 'Les adresses qui circulent en ligne ne sont pas une voie de recours officielle. Utilisez les formulaires et écrans officiels.'),
     ('Unbanz a-t-il un contact chez Meta ?', 'Non. Nous ne prétendons à aucun accès spécial : nous utilisons les mêmes voies officielles que vous.')],
    ['instagram-pas-de-bouton-faire-appel', 'droit-de-recours-dsa-meta', 'faux-hackers-arnaque-recuperation-compte', 'compte-instagram-desactive-comment-recuperer'], H_IG, std=False)

# ---------------------------------------------------------------- how it works
guide('comment-ca-marche', 'how-it-works',
    'Comment ça marche : récupération de compte avec Unbanz | Unbanz', 'Comment ça marche',
    'Comment ça marche avec Unbanz.',
    'Vous nous écrivez sur WhatsApp ou par e-mail avec votre nom d’utilisateur et une capture d’écran de la notification. Nous vous disons honnêtement si nous pouvons vous aider et le prix vous est indiqué avant le début du travail. Nous préparons ensuite la demande ou le signalement et le déposons via le processus officiel de la plateforme. Votre mot de passe reste chez vous.',
    [('etapes', 'Les étapes',
      '<ol><li><strong>Vous nous envoyez les informations</strong> : pseudo ou lien du profil, capture d’écran de la notification, date. Pour un compte publicitaire, l’identifiant du compte.</li><li><strong>Nous vous répondons</strong> : nous vous disons si nous pouvons vous aider, et quel est le prix. Il vous est indiqué dans la discussion, après que vous nous avez expliqué votre situation, avant le début du travail.</li><li><strong>Nous préparons et déposons la demande</strong> via le processus officiel de la plateforme.</li><li><strong>Nous vous tenons informé(e)</strong> jusqu’à ce qu’une réponse arrive.</li></ol>'),
     ('besoin', 'Ce dont nous avons besoin',
      '<ul><li>Votre @pseudo ou le lien du profil.</li><li>Une capture d’écran de la notification.</li><li>La date à laquelle cela s’est produit.</li></ul><p>C’est tout. <strong>Jamais de mot de passe ni de code de connexion.</strong></p>'),
     ('pas', 'Ce que nous ne faisons pas',
      '<ul><li>Nous ne demandons pas votre mot de passe.</li><li>Nous ne faisons pas de faux signalements ni de signalements en masse.</li><li>Nous n’achetons ni ne vendons de comptes.</li><li>Nous ne prétendons à aucun accès spécial chez Meta.</li></ul>'),
     ('delais', 'Délais et prix',
      '<p>Meta et Snapchat ne publient pas de délai. Nous ne promettons aucune date, mais vous tenons informé(e). Pour le prix, voyez <a href="/fr/prix-recuperation-compte/">comment il est établi</a>.</p>'),
     ('langue', 'En quelle langue ?',
      '<p>Nos échanges se font principalement en anglais, par WhatsApp ou par e-mail. Un message court suffit pour démarrer.</p>')],
    [('Comment ça se passe avec Unbanz ?', 'Vous envoyez le pseudo et la capture d’écran de la notification, nous vous disons si nous pouvons aider et à quel prix, puis nous déposons la demande via le processus officiel.'),
     ('Que dois-je vous envoyer ?', 'Le pseudo ou le lien du profil, la capture d’écran de la notification et la date. Jamais de mot de passe ni de code.'),
     ('Quand connaît-on le prix ?', 'Dans la discussion, après que vous avez expliqué votre situation et avant que le travail commence.'),
     ('Peut-on vous écrire en français ?', 'Nos échanges se font principalement en anglais. Un message court avec le pseudo, la capture d’écran et la date suffit.'),
     ('Combien de temps faut-il ?', 'Meta et Snapchat ne publient pas de délai. Nous ne pouvons promettre aucune date, mais nous vous tenons informé(e).')],
    ['services', 'prix-recuperation-compte', 'unbanz-est-il-fiable', 'faq', 'contact'],
    '<p>Prêt(e) à nous écrire ? Voir la <a href="/fr/contact/">page contact</a>.</p>', std=False, crumb_label='Services')

